const test = require('node:test');
const assert = require('node:assert/strict');
const { withoutTrack } = require('../playlist.cjs');
test('return the remaining playlist, not the removed tracks', () => {
  const tracks = Object.freeze(['intro','rain','outro']);
  assert.deepEqual(withoutTrack(tracks,1), ['intro','outro']);
  assert.deepEqual(withoutTrack(tracks,0), ['rain','outro']);
  assert.deepEqual(withoutTrack(tracks,2), ['intro','rain']);
  const same = withoutTrack(tracks,3);
  assert.deepEqual(same, tracks); assert.notStrictEqual(same,tracks);
  assert.deepEqual(withoutTrack(['solo'],0), []);
  const empty = []; const result = withoutTrack(empty,0);
  assert.deepEqual(result, []); assert.notStrictEqual(result,empty);
  const song = Object.freeze({name:'tide'});
  assert.strictEqual(withoutTrack([song,'end'],1)[0],song);
});

